import Foundation

/// Pure helpers that turn a video's `subtitles`/`automaticCaptions` maps
/// into the flat language picker the options card shows. Mirrors
/// `FormatSelection`'s "reduce yt-dlp's raw lists to what the picker needs"
/// shape.
enum SubtitleSelection {

    /// One selectable subtitle language: its yt-dlp language code and
    /// whether it's auto-generated. Sites like YouTube can offer dozens of
    /// auto-translated languages alongside a handful of manually-authored
    /// ones, so auto entries are labeled rather than mixed in unmarked.
    struct LanguageOption: Identifiable, Hashable {
        let code: String
        let isAutoGenerated: Bool

        var id: String { code }

        var label: String {
            // YouTube's "-orig" suffix marks the speech-recognition track in
            // the video's own language; it isn't a language variant itself,
            // so `displayName` leaves it out.
            let name = LanguageCode.displayName(code)
            return isAutoGenerated ? "\(name) (auto)" : name
        }
    }

    /// Every language available: manually-authored tracks first, then
    /// auto-generated ones, trimmed so the same language doesn't show up
    /// more than once:
    ///  - an auto track is dropped when a creator-added track exists for the
    ///    same language (any region), since the creator's is more accurate;
    ///  - YouTube lists a video's own language twice among the auto tracks
    ///    (`en` and `en-orig`); only the real speech-recognition one,
    ///    `-orig`, is kept.
    /// Regional manual variants (`en`, `en-GB`) stay separate — those are
    /// genuinely different tracks.
    static func languageOptions(
        subtitles: [String: [SubtitleTrackInfo]]?,
        automaticCaptions: [String: [SubtitleTrackInfo]]?
    ) -> [LanguageOption] {
        let manualCodes = Set((subtitles ?? [:]).keys)
        let manualLanguages = Set(manualCodes.map(LanguageCode.base))

        // Group auto codes by their code with any "-orig" removed, keeping
        // the "-orig" member of each group when there is one.
        var autoByKey: [String: String] = [:]
        for code in (automaticCaptions ?? [:]).keys where !manualCodes.contains(code) {
            let key = code.hasSuffix(LanguageCode.originalSuffix)
                ? String(code.dropLast(LanguageCode.originalSuffix.count))
                : code
            if autoByKey[key] == nil || code.hasSuffix(LanguageCode.originalSuffix) {
                autoByKey[key] = code
            }
        }
        let autoCodes = autoByKey.values.filter { !manualLanguages.contains(LanguageCode.base($0)) }

        let manual = manualCodes.map { LanguageOption(code: $0, isAutoGenerated: false) }
        let auto = autoCodes.map { LanguageOption(code: $0, isAutoGenerated: true) }

        return sortedByLabel(manual) + sortedByLabel(auto)
    }

    /// The language to preselect: the user's own language if there's a track
    /// for it, else English, else whatever comes first. Within a language a
    /// creator-added track beats an auto-generated one, and an exact match
    /// ("en-GB" for "en-GB") beats a looser one ("en" for "en-GB", then any
    /// other "en-…").
    static func defaultLanguageCode(
        in options: [LanguageOption],
        preferredLanguages: [String] = Locale.preferredLanguages
    ) -> String? {
        for preferred in preferredLanguages + ["en"] {
            // Creator-added tracks win (at every match tier) over any
            // auto-generated one; `min` keeps the earliest of equal matches.
            let best = options
                .compactMap { option in
                    LanguageCode.matchTier(code: option.code, preferred: preferred).map { (option: option, tier: $0) }
                }
                .min { ($0.option.isAutoGenerated ? 1 : 0, $0.tier) < ($1.option.isAutoGenerated ? 1 : 0, $1.tier) }
            if let best { return best.option.code }
        }
        return options.first?.code
    }

    /// Sorted by display name; each label is computed once, since looking one
    /// up is slow and YouTube can offer well over a hundred languages.
    private static func sortedByLabel(_ options: [LanguageOption]) -> [LanguageOption] {
        options
            .map { (option: $0, label: $0.label) }
            .sorted { $0.label.localizedCaseInsensitiveCompare($1.label) == .orderedAscending }
            .map(\.option)
    }
}
